from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod
import itertools
import numpy as np
import random

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy


def hamming_distance(a: np.ndarray, b: np.ndarray) -> int:
    return int(np.sum(a != b))

def all_vectors(dimension):
    # Yields np.ndarrays of all binary vectors of given dimension
    for num in range(2 ** dimension):
        yield np.array([(num >> i) & 1 for i in range(dimension - 1, -1, -1)], dtype=np.uint8)

def is_valid(candidate, particles_arr, min_dist):
    # candidate is 1D np.array, particles_arr: 2D np.array, shape (n_particles, dim)
    # True if candidate is at least min_dist from EACH particle
    # If no particles yet, always valid
    if particles_arr is None or len(particles_arr) == 0:
        return True
    dists = np.sum(candidate != particles_arr, axis=1)
    return np.all(dists >= min_dist)

class ExclusivityParticlesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        distance = data['distance']
        cnt_particles = data['particles']

        next_particle = None
        # Prepare particle array for vectorized Hamming calculations
        if cnt_particles:
            particles_arr = np.array(cnt_particles, dtype=np.uint8)
        else:
            particles_arr = None

        # --- CASE 1: First move ---
        if not cnt_particles:
            next_particle = [0] * dimension
        else:
            # For small dimensions, enumerate exhaustively
            max_enum_dim = 16   # Up to 2^16=65536 - reasonable in under a sec
            # Precompute a set of already played tuples for instant skip
            played_set = set(tuple(p) for p in cnt_particles)
            found = False
            # Canonical symmetric choices first: [all-zeros], [all-ones], and half-half if even
            candidate_orientations = [np.zeros(dimension, dtype=np.uint8),
                                      np.ones(dimension, dtype=np.uint8)]
            if dimension % 2 == 0:
                arr = np.array([0]*(dimension//2) + [1]*(dimension//2), dtype=np.uint8)
                candidate_orientations.append(arr)
                arr2 = np.array([1]*(dimension//2) + [0]*(dimension//2), dtype=np.uint8)
                candidate_orientations.append(arr2)
            for cand in candidate_orientations:
                tup = tuple(cand.astype(int))
                if tup not in played_set and is_valid(cand, particles_arr, distance):
                    next_particle = cand.tolist()
                    found = True
                    break
            # Now try all possible vectors (exhaustive, if dimension not too big)
            if not found and dimension <= max_enum_dim:
                for cand in all_vectors(dimension):
                    tup = tuple(cand.tolist())
                    if tup in played_set:
                        continue
                    if is_valid(cand, particles_arr, distance):
                        next_particle = cand.tolist()
                        found = True
                        break
            # For large dimensions, use random sampling
            if not found and dimension > max_enum_dim:
                attempts = 200000 if dimension > 20 else 50000
                for _ in range(attempts):
                    cand = np.random.randint(0, 2, size=dimension, dtype=np.uint8)
                    tup = tuple(cand.tolist())
                    if tup in played_set:
                        continue
                    if is_valid(cand, particles_arr, distance):
                        next_particle = cand.tolist()
                        found = True
                        break
            # Still not found, fail
            if not found:
                next_particle = None
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_particle, type='custom')]
        )

