        placed_set = set(tuple(p) for p in cnt_particles)
        next_particle = None

        # Quick shortcut: if no particles have been placed yet, return all-zeros
        if len(cnt_particles) == 0:
            next_particle = [0]*dimension
        else:
            # For reasonably small dimension, check all possible candidates
            for candidate in self.generate_all_candidates(dimension):
                c_tuple = tuple(candidate)
                if c_tuple in placed_set:
                    continue
                # Check Hamming distance from all placed
                if all(self.hamming_distance(candidate, p) >= distance for p in cnt_particles):
                    next_particle = candidate
                    break
            # If none found, return None

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_particle, type='custom')]
        )

